public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    int[] count = new int[k];

    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        count[remainder]++;
    }

    // Check remainder 0: must be even
    if (count[0] % 2 != 0) {
        return false;
    }

    // Check pairs of remainders i and k-i
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) {
            // This happens when k is even and i = k/2
            if (count[i] % 2 != 0) {
                return false;
            }
        } else {
            if (count[i] != count[k - i]) {
                return false;
            }
        }
    }

    return true;
}

