public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    fibs.add(b);
    while (true) {
        int c = a + b;
        if (c > k) break;
        fibs.add(c);
        a = b;
        b = c;
    }

    // Greedy approach: pick the largest Fibonacci number <= remaining k
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (fibs.get(i) <= remaining) {
            remaining -= fibs.get(i);
            count++;
            if (remaining == 0) break;
        }
    }
    return count;
}

