public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    int absN = Math.abs(n);
    String s = String.valueOf(absN);
    StringBuilder sb = new StringBuilder();
    int len = s.length();
    for (int i = 0; i < len; i++) {
        sb.append(s.charAt(i));
        int remaining = len - i - 1;
        if (remaining > 0 && remaining % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

