    java.util.Set<Integer> uniqueElements = new java.util.HashSet<>();
    for (int num : nums) {
        uniqueElements.add(num);
    }
    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }
    return sum;
}

